CREATE TYPE app.org_status AS ENUM ('trial', 'active', 'suspended', 'deleted');
CREATE TYPE app.audit_action AS ENUM ('created', 'updated', 'deleted', 'login');
CREATE TYPE app.money_amount AS (
    amount NUMERIC(14, 2),
    currency CHAR(3)
);

CREATE TABLE app.organizations (
    org_id BIGINT GENERATED ALWAYS AS IDENTITY,
    slug TEXT NOT NULL,
    status app.org_status NOT NULL DEFAULT 'trial',
    billing_limit app.money_amount,
    search_slug TEXT GENERATED ALWAYS AS (lower(slug)) STORED,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id),
    CONSTRAINT uq_organizations_slug UNIQUE (slug),
    CONSTRAINT chk_org_status CHECK (status <> 'deleted' OR billing_limit IS NOT NULL)
);

CREATE TABLE app.users (
    org_id BIGINT NOT NULL REFERENCES app.organizations(org_id),
    user_id UUID NOT NULL,
    email TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'member',
    status app.org_status NOT NULL DEFAULT 'active',
    PRIMARY KEY (org_id, user_id),
    CONSTRAINT uq_users_email UNIQUE (org_id, email)
);

CREATE TABLE app.audit_events (
    org_id BIGINT NOT NULL,
    event_id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    user_id UUID,
    action app.audit_action NOT NULL,
    subject_table TEXT NOT NULL,
    payload JSONB NOT NULL DEFAULT jsonb_build_object(),
    PRIMARY KEY (org_id, event_id),
    CONSTRAINT fk_audit_user
        FOREIGN KEY (org_id, user_id)
        REFERENCES app.users(org_id, user_id)
);

CREATE INDEX idx_users_role_status
    ON app.users (role, status)
    WHERE status = 'active';

CREATE INDEX idx_audit_subject_action
    ON app.audit_events (subject_table, action);
